PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      role TEXT NOT NULL CHECK(role IN ('ADMIN', 'BIAL')),
      bial_name TEXT,
      status TEXT DEFAULT 'active' CHECK(status IN ('active', 'locked')),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , email TEXT, google_id TEXT);
CREATE TABLE bials (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      code TEXT NOT NULL,
      user_id INTEGER,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
CREATE TABLE members (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      bial_id INTEGER NOT NULL,
      sl_no INTEGER NOT NULL,
      name TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP, year INTEGER DEFAULT 2026,
      FOREIGN KEY (bial_id) REFERENCES bials(id) ON DELETE CASCADE
    );
CREATE TABLE month_locks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      bial_id INTEGER NOT NULL,
      year INTEGER NOT NULL,
      month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12),
      is_locked INTEGER DEFAULT 0 CHECK(is_locked IN (0, 1)),
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(bial_id, year, month)
    );
CREATE TABLE tithes (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      member_id INTEGER NOT NULL,
      bial_id INTEGER NOT NULL,
      year INTEGER NOT NULL,
      month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12),
      pathian_ram REAL DEFAULT 0,
      ramthar REAL DEFAULT 0,
      tualchhung REAL DEFAULT 0,
      building REAL DEFAULT 0,
      total REAL DEFAULT 0,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, extra_amounts TEXT DEFAULT '{}',
      UNIQUE(member_id, year, month),
      FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
      FOREIGN KEY (bial_id) REFERENCES bials(id) ON DELETE CASCADE
    );
CREATE TABLE financial_years (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      year INTEGER UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , is_active INTEGER DEFAULT 0);
CREATE TABLE tithe_columns (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT NOT NULL, field_key TEXT UNIQUE NOT NULL, color TEXT DEFAULT '#6366f1', display_order INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_google_emails (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
DELETE FROM sqlite_sequence;
